SELECT id, order_id, shipped_date, delivered_date, cost, status, LAG(cost, 1) OVER (PARTITION BY status, carrier ORDER BY shipped_date, id) AS prev_cost, ROUND(cost / SUM(cost) OVER (PARTITION BY status), 4) AS cost_share, LEAD(cost, 2, 0) OVER (PARTITION BY MONTH(delivered_date), order_id ORDER BY shipped_date, id) AS next_cost, DENSE_RANK() OVER (PARTITION BY carrier, status ORDER BY cost DESC NULLS LAST) AS cost_dense_rank, ROW_NUMBER() OVER (PARTITION BY status ORDER BY delivered_date, id) AS event_seq FROM shipments
